// Each paid order gets a delivery record. The same new record is linked to
// the order and marked ready; two orders get different records. A blank node
// in an N3 conclusion becomes a Skolem witness that C8 checks per firing.
//
// Compiled from examples/n3-witnesses.n3 by eyemind: eyemind --program examples/n3-witnesses.n3.
// The generated program below runs directly in eyemind and the playground.

// Generated by eyemind from examples/n3-witnesses.n3, Notation3.
// Each N3 triple is rdf(Subject, Predicate, Object). Without a log:query
// the conclusions are the triples the forward rules derive.
fact(rdf(iri("https://example.org/delivery#order1"), iri("https://example.org/delivery#status"), iri("https://example.org/delivery#paid")))
fact(rdf(iri("https://example.org/delivery#order2"), iri("https://example.org/delivery#status"), iri("https://example.org/delivery#paid")))
implies(rdf(Order, iri("https://example.org/delivery#status"), iri("https://example.org/delivery#paid")), [rdf(Order, iri("https://example.org/delivery#delivery"), Bdelivery), rdf(Bdelivery, iri("https://example.org/delivery#status"), iri("https://example.org/delivery#ready"))])
